import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    static int MAX_R = 40;
    static int MAX_C = 40;
    static int MAX_K = 100;

    static class Matrix extends ArrayList<List<Long>> {
        public Matrix() {
            super();
        }
        public static Matrix create(int r, int c) {
            Matrix M = new Matrix();
            for (int i = 0; i < r; i++) {
                List<Long> row = new ArrayList<>();
                for (int j = 0; j < c; j++) {
                    row.add(0L);
                }
                M.add(row);
            }
            return M;
        }
    }

    static long N;
    static int K;
    static Matrix[] R = new Matrix[40];
    static Matrix[][][] D = new Matrix[101][40][];
    // D[i][j] is an array of matrices, size depends on j

    static void makeMatrix(Matrix M, int r, int c) {
        M.clear();
        for (int i = 0; i < r; i++) {
            List<Long> row = new ArrayList<>();
            for (int j = 0; j < c; j++) {
                row.add(0L);
            }
            M.add(row);
        }
    }

    static Matrix multiplyMatrices(Matrix A, Matrix B) {
        int rA = A.size();
        int cA = A.get(0).size();
        int rB = B.size();
        int cB = B.get(0).size();
        Matrix C = Matrix.create(rA, cB);
        for (int i = 0; i < rA; i++) {
            for (int j = 0; j < cB; j++) {
                long sum = 0;
                for (int k = 0; k < cA; k++) {
                    sum += A.get(i).get(k) * B.get(k).get(j);
                }
                C.get(i).set(j, sum);
            }
        }
        return C;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        N = sc.nextLong();
        K = sc.nextInt();

        int count = 0;
        long p = 1;
        while (p <= N) {
            p *= K;
            count++;
        }
        p /= K;

        int[] digits = new int[count];
        long tempN = N;
        long tempP = p;
        for (int i = 0; i < count; i++) {
            digits[i] = (int)(tempN / tempP);
            tempN %= tempP;
            tempP /= K;
        }

        for (int i = 0; i <= K; i++) {
            R[i] = Matrix.create(K + 1, K + 1);
        }
        for (int i = 0; i <= count; i++) {
            for (int j = 0; j < K; j++) {
                D[i][j] = new Matrix[1];
                D[i][j][0] = Matrix.create(K + 1, K + 1);
            }
        }

        // Initialize R[0] and R[1]
        R[0].get(K).set(K, 1L);
        R[1].get(K).set(K, 1L);
        for (int j = 0; j < K; j++) {
            R[0].get(j).set(j, 1L);
        }
        for (int j = 0; j < K; j++) {
            R[1].get((j + K - 1) % K).set(j, 1L);
        }
        for (int j = 2; j <= K; j++) {
            R[j] = multiplyMatrices(R[j - 1], R[1]);
        }

        // Initialize D[0][0]
        for (int j = 0; j < K; j++) {
            D[0][0][j] = Matrix.create(K + 1, K + 1);
            D[0][0][j].get(j).set(j, 1L);
            D[0][0][j].get(0).set(0, 1L);
        }

        int total_count = count;
        for (int i = 0; i <= total_count; i++) {
            for (int j = 1; j < K; j++) {
                // D[i][j] = R[K - j] * D[i][0] * R[j]
                Matrix temp1 = multiplyMatrices(R[K - j], D[i][0]);
                D[i][j] = multiplyMatrices(temp1, R[j]);
            }
            if (i + 1 <= total_count) {
                D[i + 1][0] = D[i][K - 1];
            }
        }

        Matrix answer = Matrix.create(1, K + 1);
        answer.get(0).set(K, 1L);
        int sum_modulo = 0;
        for (int i = 0; i < total_count; i++) {
            if (digits[i] != 0) {
                Matrix temp1 = multiplyMatrices(R[K - sum_modulo], D[total_count - i - 1][digits[i] - 1]);
                answer = multiplyMatrices(temp1, R[sum_modulo]);
            }
            sum_modulo += digits[i];
            sum_modulo %= K;
        }

        long total_result = 0;
        for (int i = 0; i <= K; i++) {
            total_result += answer.get(0).get(i);
        }
        System.out.println(total_result);
        sc.close();
    }
}

